import React, { useEffect, useRef, useState } from 'react';
import { Badge, Button, Form, Spinner } from 'react-bootstrap';
import { reportFilterFormContainer, staffSalaryBtn } from './formFieldData';
import Table from '../../../components/Table';
import { dateConversion, findArrObj, showConfirmationDialog, showMessage } from '../../../utils/AllFunction';
import { usePageTitle, useRedux } from '../../../hooks'
import { NotificationContainer } from 'react-notifications';
import {
    getBranchRequest, getDepartmentRequest, resetGetBranch, resetGetDepartment,
    createStaffLeaveRequest,
    getStaffLeaveRequest,
    getStaffRequest,
    resetCreateStaffLeave,
    resetGetStaff,
    resetGetStaffLeave,
    resetUpdateStaffLeave,
    updateStaffLeaveRequest,
} from '../../../redux/actions';
import moment from 'moment';
import * as XLSX from "xlsx";
import { useNavigate } from 'react-router-dom';
import _ from 'lodash';
import noProfile from '../../../assets/images/noprofile_images.jpg';
import { baseURL } from '../../../api/ApiConfig';

function Index() {

    usePageTitle({
        title: 'Report',
        breadCrumbItems: [
            {
                path: '/report/leave-report',
                label: 'Report',
            },
            {
                path: '/report/leave-report',
                label: 'Leave Report',
                active: true,
            },
        ],
    });

    const { dispatch, appSelector } = useRedux();
    const loginInfo = localStorage.getItem('loginInfo');
    const localData = JSON.parse(loginInfo);
    const pageAccessData = findArrObj(localData[0].pagePermission, 'label', "Leave Report");
    const accessIds = (pageAccessData[0]?.access || '').split(',').map(id => id.trim()); // for access create and update and delete actions ['1', '2', '3', '4', '5', '6']
    const branchIdforRole = localData[0]?.branchId || 0; // for branch list can only show
    const roleIdforRole = localData[0].roleId; // for role Permission (1.superadmin,2.admin)

    const incentiveAmountRefs = useRef([]);
    const navigate = useNavigate();

    const {
        getBranchSuccess, getBranchList, getBranchFailure,
        getDepartmentSuccess, getDepartmentList, getDepartmentFailure,
        getStaffLeaveSuccess,
        getStaffLeaveList,
        getStaffLeaveFailure,
        errorMessage,
    } = appSelector((state) => ({

        getBranchSuccess: state.branchReducer.getBranchSuccess,
        getBranchList: state.branchReducer.getBranchList,
        getBranchFailure: state.branchReducer.getBranchFailure,

        getDepartmentSuccess: state.departmentReducer.getDepartmentSuccess,
        getDepartmentList: state.departmentReducer.getDepartmentList,
        getDepartmentFailure: state.departmentReducer.getDepartmentFailure,

        getStaffLeaveSuccess: state.staffLeaveReducer.getStaffLeaveSuccess,
        getStaffLeaveList: state.staffLeaveReducer.getStaffLeaveList,
        getStaffLeaveFailure: state.staffLeaveReducer.getStaffLeaveFailure,



        errorMessage: state.staffLeaveReducer.errorMessage,

        errorMessage: state.claimReducer.errorMessage,
    }));

    const columns = [
        {
            Header: 'S.No',
            accessor: 'id',
            Cell: (row) => <div>{row?.row?.index + 1}</div>,
        },
        {
            Header: "Staff",
            accessor: 'staffName',
            Cell: ({ row }) => (
                <div className="inbox-item-img" style={{ display: 'flex', alignItems: 'center' }}>
                    <img
                        src={row?.original?.staffProfile ? `${baseURL}${row?.original.staffProfile}` : noProfile}
                        alt="staffProfile"
                        className="rounded-circle"
                        crossOrigin="anonymous"
                        onError={(e) => {
                            e.target.onerror = null;
                            e.target.src = noProfile;
                        }}
                        style={{ width: "40px", height: "40px", objectFit: "cover", marginRight: "10px" }}
                    />
                    <div>
                        <div style={{ fontSize: '15px', fontWeight: '600' }}>
                            {row?.original?.staffName}
                        </div>
                        <div style={{ fontSize: '12px', color: '#888' }}>
                            {row?.original?.staffCode}
                        </div>
                    </div>
                </div>
            )
        },
        {
            Header: 'Leave Type',
            accessor: 'leaveTypeName',
            sort: true,
        },
        {
            Header: 'From Date',
            accessor: 'fromDate',
            Cell: ({ row }) => {
                return <div>{dateConversion(row.original.fromDate, 'DD-MM-YYYY')}</div>;
            },
        },
        {
            Header: 'To Date',
            accessor: 'toDate',
            Cell: ({ row }) => {
                return <div>{dateConversion(row.original.toDate, 'DD-MM-YYYY')}</div>;
            },
        },
        {
            Header: 'Reason',
            accessor: 'reason',
            sort: true,
        },
        {
            Header: 'Status',
            accessor: 'status',
            Cell: ({ row }) => (
                <Badge
                    bg={
                        row.original.statusId === 30
                            ? 'danger'
                            : row.original.statusId === 28
                                ? 'primary'
                                : 'success'
                    }>
                    {row.original.statusId === 30
                        ? 'Cancelled'
                        : row.original.statusId === 28
                            ? 'Request'
                            : 'Approved'}
                </Badge>
            ),
        },
        {
            Header: 'Actions',
            accessor: 'actions',
            Cell: ({ row }) => {
                const passData = {
                    isLeave: true,
                    staffName: row.original?.staffName || "",
                    designationName: row.original?.designationName,
                    typeName: `${row.original?.dayCount || 0} days`,
                    fromDate: row.original?.fromDate,
                    toDate: row.original?.toDate,

                    spokenStaffName: row.original?.spokenStaffName,
                    spokenDesignationName: row.original?.spokenDesignationName,
                    spokenTime: row.original?.spokenTime,
                    spokenDate: row.original?.spokenDate,
                    reason: row.original?.reason
                }
                return (
                    <div>
                        {/* {
                             (roleIdforRole == 1 || _.includes(accessIds, '2')) && row.original.statusId === 28 &&
                             <span
                                 className="text-primary  me-2 cursor-pointer"
                                 onClick={() => onEditForm(row.original, row.index)}>
                                 <i className={'fe-edit-1'}></i>
                             </span>
                         } */}
                        {/* {roleIdforRole == 1 && row.original.statusId === 28 && (
                             <span>
                                 <span
                                     className={`text-success me-2 cursor-pointer`}
                                     onClick={() =>
                                         showConfirmationDialog(
                                             'You want to Approved?',
                                             () => onStatusForm(row.original, row.index, 29),
                                             'Yes'
                                         )
                                     }>
                                     <i className={'fe-thumbs-up'}></i>
                                 </span>
                                 <span
                                     className={`text-danger cursor-pointer`}
                                     onClick={() =>
                                         showConfirmationDialog(
                                             'You want to Cancelled?',
                                             () => onStatusForm(row.original, row.index, 30),
                                             'Yes'
                                         )
                                     }>
                                     <i className={'fe-thumbs-down'}></i>
                                 </span>
                             </span>
                         )} */}

                        {
                            row.original.statusId == 29 && (
                                <div>
                                    <span className="text-success  me-2 cursor-pointer"
                                        onClick={() => navigate('/leave-slip-report', { state: passData })}>
                                        <i className={'fe-printer'} style={{ fontSize: '19px' }}></i>
                                    </span>
                                </div>
                            )
                        }
                    </div>
                );
            },
        },
    ];
    const onFromDate = (event, formName) => {
        setState({
            ...state,
            [formName]: event.target.value
        })
        const filterDate = {
            fromDate: event.target.value,
            toDate: state.toDate,
            durationId: state.durationId,
            branchId: state.branchId || '',
            staffId: state.staffId || '',
            departmentId: state.departmentId || '',
        }
        dispatch(getStaffLeaveRequest(filterDate));
    }
    const onToDate = (event, formName) => {
        setState({
            ...state,
            [formName]: event.target.value
        })
        const filterDate = {
            toDate: event.target.value,
            fromDate: state.fromDate,
            durationId: state.durationId,
            branchId: state.branchId || '',
            staffId: state.staffId || '',
            departmentId: state.departmentId || '',
        }
        dispatch(getStaffLeaveRequest(filterDate));
    }
    const [state, setState] = useState({
        fromDate: moment().subtract(1, 'months').format('YYYY-MM-DD'),
        toDate: moment().format('YYYY-MM-DD'),
        durationId: 0,
        departmentId: 0,
        branchId: branchIdforRole
    });
    const [optionListState, setOptionListState] = useState({
        departmentList: [
            {
                "departmentId": 0,
                "departmentName": "All",
            },
        ],
        branchList: [{
            "branchId": 0,
            "branchName": "All",
        }],
        durationList: [
            {
                "durationId": 0,
                "durationName": "Month",
            },
            {
                "durationId": 1,
                "durationName": "Year",
            },
        ]
    })
    const [parentList, setParentList] = useState([]);
    const [formContain, setFormContain] = useState(reportFilterFormContainer);
    const [isLoading, setIsLoading] = useState(false);

    useEffect(() => {
        setIsLoading(true)
        dispatch(getBranchRequest());
        dispatch(getDepartmentRequest());
        const searchReq = {
            fromDate: state?.fromDate,
            toDate: state?.toDate,
            durationId: state.durationId,
            branchId: branchIdforRole || '',
            departmentId: state.departmentId || '',
        }
        dispatch(getStaffLeaveRequest(searchReq));
    }, []);

    useEffect(() => {
        if (roleIdforRole != 1) {
            let arr = reportFilterFormContainer;
            const updatedFormFields = _.filter(
                reportFilterFormContainer[0].formFields,
                (field) => field.name !== 'branchId'
            );
            arr[0].formFields = updatedFormFields;
            setFormContain(arr);
        }
    }, [reportFilterFormContainer, roleIdforRole]);


    useEffect(() => {
        if (getBranchSuccess) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                branchList: [...optionListState.branchList, ...getBranchList],
            })
            dispatch(resetGetBranch())
        } else if (getBranchFailure) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                branchList: []
            })
            dispatch(resetGetBranch())
        }
    }, [getBranchSuccess, getBranchFailure]);

    useEffect(() => {
        if (getDepartmentSuccess) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                departmentList: [...optionListState.departmentList, ...getDepartmentList],
            })
            dispatch(resetGetDepartment())
        } else if (getDepartmentFailure) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                departmentList: []
            })
            dispatch(resetGetDepartment())
        }
    }, [getDepartmentSuccess, getDepartmentFailure]);

    useEffect(() => {
        if (getStaffLeaveSuccess) {
            setIsLoading(false)
            setParentList(getStaffLeaveList)

            setIsLoading(false);
            dispatch(resetGetStaffLeave())
        } else if (getStaffLeaveFailure) {
            setIsLoading(false)
            setParentList([])
            dispatch(resetGetStaffLeave())
        }
    }, [getStaffLeaveSuccess, getStaffLeaveFailure]);

    const onPrintDesign = (data) => {
        if (data?.claimTypeId == 1) {
            navigate('/birthday-claim-report', { state: data });
        } else {
            navigate('/common-claim-report', { state: data });
        }
        return;
    }

    const onDateFilter = (event, formName) => {
        setState({
            ...state,
            [formName]: event.target.value
        })
        const filterDate = {
            applyDate: event.target.value,
            durationId: state.durationId,
            branchId: state.branchId || '',
            departmentId: state.departmentId || '',
        }
        dispatch(getStaffLeaveRequest(filterDate));
    }

    const onDurationFilter = (item, formName) => {
        setState({
            ...state,
            [formName]: item.durationId,
        })
        const filterDuration = {
            durationId: item.durationId,
            // applyDate: state?.applyDate,
            fromDate: state?.fromDate,
            toDate: state?.toDate,
            branchId: state.branchId || '',
            departmentId: state.departmentId || '',
        }
        dispatch(getStaffLeaveRequest(filterDuration));
    }


    const onDepartmentFilter = (option, formName, uniqueKey, displayKey) => {
        const filterDepartment = {
            departmentId: option[uniqueKey] || '',
            branchId: state?.branchId || '',
            // applyDate: state?.applyDate,
            fromDate: state?.fromDate,
            toDate: state?.toDate,
            durationId: state.durationId,
        }
        dispatch(getStaffLeaveRequest(filterDepartment));
        setIsLoading(true);
        setState({
            ...state,
            [formName]: option[uniqueKey],
        })
    }

    const onBranchFilter = (option, formName, uniqueKey, displayKey) => {
        const filterBranch = {
            branchId: option[uniqueKey] || '',
            departmentId: state?.departmentId || '',
            // applyDate: state?.applyDate,
            fromDate: state?.fromDate,
            toDate: state?.toDate,
            durationId: state.durationId,
        }
        dispatch(getStaffLeaveRequest(filterBranch));
        setState({
            ...state,
            [formName]: option[uniqueKey],
        })
    }

    const onDownload = () => {
        const yearMonth = moment(state?.fromDate).format("MMMM YYYY") + " to " + moment(state?.toDate).format("MMMM YYYY");
        const additionalDetails = `Leave Report for ${yearMonth}`;
        const reportGeneratedDate = `Report Generated On: ${moment().format("DD-MM-YYYY")}`;
        const data = parentList.map((item, i) => ({
            ["s.no"]: i + 1,
            staffName: item.staffName,
            leaveTypeName: item.leaveTypeName,
            fromDate: moment(item.fromDate).format("DD-MM-YYYY"),
            toDate: moment(item.toDate).format("DD-MM-YYYY"),
            Reason: item.reason,
            statusName: item.statusName
        }));
        const header = [
            [additionalDetails],
            [reportGeneratedDate],
            [],
            ["S.no", "Staff Name", "Leave Type", "From Date", "To Date", "Reason", "Status"]
        ];
        const rows = [
            ...header,
            ...data.map(item => [
                item["s.no"],
                item.staffName,
                item.leaveTypeName,
                item.fromDate,
                item.toDate,
                item.Reason,
                item.statusName,
            ])
        ];
        const worksheet = XLSX.utils.aoa_to_sheet(rows);

        worksheet["!cols"] = [
            { wch: 10 },
            { wch: 20 },
            { wch: 20 },
            { wch: 15 },
            { wch: 15 },
            { wch: 12 },
            { wch: 12 },
            { wch: 10 },
            { wch: 12 },
            { wch: 12 },
            { wch: 12 },
            { wch: 12 },
        ];

        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, "Leave Report");

        XLSX.writeFile(workbook, `K3-Leave-Report-${yearMonth}.xlsx`);
    };


    return (
        <React.Fragment>
            <NotificationContainer />
            {isLoading ? <div className='bg-light opacity-0.25'>
                <div className="d-flex justify-content-center m-5">
                    <Spinner className='mt-5 mb-5' animation="border" />
                </div>
            </div> :
                <Table
                    columns={columns}
                    Title={'Leave Report List'}
                    data={parentList || []}
                    pageSize={5}
                    toggle={false}
                    pagination={false}
                    filterTbl={true}
                    footerTbl={true}
                    filterFormContainer={formContain}
                    // onChangeCallBack={{ "onDateFilter": onDateFilter, "onDepartmentFilter": onDepartmentFilter, "onBranchFilter": onBranchFilter, "onDurationFilter": onDurationFilter }}
                    onChangeCallBack={{ "onToDate": onToDate, "onFromDate": onFromDate, "onDepartmentFilter": onDepartmentFilter, "onBranchFilter": onBranchFilter, "onDurationFilter": onDurationFilter }}

                    onClickCallBack={{ "onDownload": onDownload }}
                    optionListState={optionListState}
                    setState={setState}
                    state={state}
                    noOfColumns={1}
                />}
        </React.Fragment>
    );
}

export default Index;
